// Generated by Cypress Author on 2026-10-19
//
// AUT 03 · PAR 04 · USU 08 · CON 07 (P0) — Plano_de_Testes_QA_MatchWallet.md §3, §4, §9.2, §11.
// Autorização no SERVIDOR: esconder menu não basta. Cada chamada administrativa é feita com a
// sessão de um CLIENTE, fora da interface, e precisa ser negada sem devolver nem alterar dados.
// Requer backend + banco de teste e as credenciais `cliente*`/`admin*` em cypress.env.json.

const NEGADO = [401, 403]

describe('Plano QA · Autorização no servidor (cliente não administra)', () => {
  beforeEach(() => {
    cy.loginReal('cliente')
  })

  it('AUT 03 · cliente abre rotas administrativas pela URL → a aplicação o leva para /403', () => {
    for (const rota of ['/admin', '/admin/usuarios', '/admin/carteiras', '/admin/configuracoes']) {
      cy.visit(rota)
      cy.location('pathname').should('eq', '/403')
    }
  })

  it('AUT 03 · cliente chama leituras e escritas administrativas da API → todas negadas, sem dados administrativos', () => {
    const leituras = ['/usuarios', '/dashboard/admin']
    for (const url of leituras) {
      cy.apiRequest({ method: 'GET', url, failOnStatusCode: false }).then(({ status, body }) => {
        expect(status, `GET ${url}`).to.be.oneOf(NEGADO)
        expect(JSON.stringify(body), `corpo de GET ${url}`).not.to.contain('"items"')
      })
    }

    const escritas = [
      { method: 'POST', url: '/carteiras', body: { nome: 'Invasora', perfilAlvo: 'MODERADO' } },
      {
        method: 'POST',
        url: '/relatorios/gerar',
        body: { carteiraId: 'x', mesReferencia: '2026-10' },
      },
    ]
    for (const requisicao of escritas) {
      cy.apiRequest({ ...requisicao, failOnStatusCode: false })
        .its('status', { log: false })
        .should('be.oneOf', NEGADO)
    }
  })

  it('PAR 04 · cliente tenta alterar as faixas de suitability → negado e a configuração permanece', () => {
    const faixas = [
      { perfil: 'CONSERVADOR', min: 0, max: 50 },
      { perfil: 'MODERADO', min: 51, max: 52 },
      { perfil: 'ARROJADO', min: 53, max: 54 },
      { perfil: 'SOFISTICADO', min: 55, max: 60 },
    ]

    cy.apiRequest({
      method: 'PUT',
      url: '/configuracoes/suitability',
      body: { escalaMaxima: 60, faixas },
      failOnStatusCode: false,
    })
      .its('status')
      .should('be.oneOf', NEGADO)

    // Confere como admin que nada mudou (a versão vigente não tem a faixa forjada).
    cy.loginReal('admin')
    cy.apiRequest<{ faixas: Array<{ perfil: string; max: number }> }>({
      method: 'GET',
      url: '/configuracoes/suitability',
    }).then(({ body }) => {
      const conservador = body.faixas.find((f) => f.perfil === 'CONSERVADOR')
      expect(conservador?.max).not.to.eq(50)
    })
  })

  it('USU 08 · cliente tenta promover a própria conta a admin → negado e o papel continua cliente', () => {
    cy.apiRequest<{ id: string }>({ method: 'GET', url: '/auth/me' }).then(({ body: eu }) => {
      cy.apiRequest({
        method: 'PATCH',
        url: `/usuarios/${eu.id}`,
        body: { perfil: 'admin' },
        failOnStatusCode: false,
      })
        .its('status')
        .should('be.oneOf', NEGADO)
    })

    cy.apiRequest<{ perfil: string }>({ method: 'GET', url: '/auth/me' })
      .its('body.perfil')
      .should('eq', 'cliente')
  })

  it('CON 07 · cliente injeta papel e carteira no PATCH da própria conta → privilégio e vínculo ficam intactos', () => {
    cy.apiRequest<{ perfil: string; carteiraVinculada: unknown }>({
      method: 'GET',
      url: '/auth/me',
    }).then(({ body: antes }) => {
      cy.apiRequest({
        method: 'PATCH',
        url: '/auth/me',
        body: { perfil: 'admin', carteiraId: '00000000-0000-4000-8000-000000000000' },
        failOnStatusCode: false,
      })
        // Aceitar ou rejeitar é decisão do contrato; o que não pode é o servidor obedecer.
        .its('status')
        .should('not.be.within', 500, 599)

      cy.apiRequest<{ perfil: string; carteiraVinculada: unknown }>({
        method: 'GET',
        url: '/auth/me',
      }).then(({ body: depois }) => {
        expect(depois.perfil).to.eq('cliente')
        expect(depois.carteiraVinculada).to.deep.eq(antes.carteiraVinculada)
      })
    })
  })
})

export {}
